package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultActions;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MemberActiveLoanIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void active_loans_are_listed_with_title_and_due_date_and_total_count() throws Exception {
        String memberId = registerMember();
        String bookId = registerBook("Clean Code");
        loanBook(bookId, memberId, "2026-02-02");

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].bookId").value(bookId))
                .andExpect(jsonPath("$.items[0].title").value("Clean Code"))
                .andExpect(jsonPath("$.items[0].loanedAt").value("2026-02-02"))
                .andExpect(jsonPath("$.items[0].dueAt").value("2026-02-16"))
                .andExpect(jsonPath("$.items[0].loanId").isNotEmpty())
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(20))
                .andExpect(jsonPath("$.totalCount").value(1));
    }

    @Test
    void returned_loans_are_excluded() throws Exception {
        String memberId = registerMember();
        String returnedLoanId = loanBook(registerBook("Returned Book"), memberId, "2026-02-02");
        loanBook(registerBook("Still Out"), memberId, "2026-02-03");

        mockMvc.perform(post("/loans/{loanId}/return", returnedLoanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-02-05\"}"))
                .andExpect(status().isOk());

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].title").value("Still Out"))
                .andExpect(jsonPath("$.totalCount").value(1));
    }

    @Test
    void pages_are_sliced_and_total_count_ignores_page() throws Exception {
        String memberId = registerMember();
        loanBook(registerBook("First"), memberId, "2026-02-01");
        loanBook(registerBook("Second"), memberId, "2026-02-02");
        loanBook(registerBook("Third"), memberId, "2026-02-03");

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "0").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(2))
                .andExpect(jsonPath("$.items[0].title").value("First"))
                .andExpect(jsonPath("$.items[1].title").value("Second"))
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(2))
                .andExpect(jsonPath("$.totalCount").value(3));

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "1").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].title").value("Third"))
                .andExpect(jsonPath("$.page").value(1))
                .andExpect(jsonPath("$.totalCount").value(3));

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "5").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(0))
                .andExpect(jsonPath("$.totalCount").value(3));
    }

    @Test
    void member_without_loans_gets_empty_list() throws Exception {
        mockMvc.perform(get("/members/{memberId}/loans", registerMember()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(0))
                .andExpect(jsonPath("$.totalCount").value(0));
    }

    @Test
    void listing_loans_of_an_unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}/loans", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void invalid_paging_parameters_return_400() throws Exception {
        String memberId = registerMember();

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "-1"))
                .andExpect(status().isBadRequest());
        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("size", "0"))
                .andExpect(status().isBadRequest());
        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("size", "101"))
                .andExpect(status().isBadRequest());
    }

    private String registerMember() throws Exception {
        return readId(mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"김민지\"}")), "memberId");
    }

    private String registerBook(String title) throws Exception {
        return readId(mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}")), "id");
    }

    private String loanBook(String bookId, String memberId, String loanedAt) throws Exception {
        return readId(mockMvc.perform(post("/loans")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId
                                + "\",\"loanedAt\":\"" + loanedAt + "\"}")), "loanId");
    }

    private String readId(ResultActions result, String field) throws Exception {
        String body = result.andReturn().getResponse().getContentAsString();
        JsonNode node = objectMapper.readTree(body);
        return node.get(field).asText();
    }
}
package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultActions;

import java.time.LocalDate;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class LendingIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void loaning_a_book_already_on_loan_returns_409() throws Exception {
        String memberId = registerMember();
        String loanRequest = loanRequest(registerBook(), memberId);

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest))
                .andExpect(status().isCreated());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest))
                .andExpect(status().isConflict());
    }

    @Test
    void loaning_with_an_unregistered_member_returns_404() throws Exception {
        String loanRequest = loanRequest(registerBook(), UUID.randomUUID().toString());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest))
                .andExpect(status().isNotFound());
    }

    @Test
    void member_can_hold_five_loans_but_the_sixth_returns_409() throws Exception {
        String memberId = registerMember();

        for (int i = 0; i < 5; i++) {
            mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                            .content(loanRequest(registerBook(), memberId)))
                    .andExpect(status().isCreated());
        }

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(registerBook(), memberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("LOAN_LIMIT_EXCEEDED"));
    }

    @Test
    void sponsor_registered_with_given_id_can_hold_more_than_five_loans() throws Exception {
        String memberId = "11111111-1111-1111-1111-111111111111";
        mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"memberId\":\"" + memberId + "\",\"name\":\"후원자\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.memberId").value(memberId));

        for (int i = 0; i < 6; i++) {
            mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                            .content(loanRequest(registerBook(), memberId)))
                    .andExpect(status().isCreated());
        }
    }

