        String returnedLoanId = loanBook(registerBook("Clean Code"), memberId, "2026-03-02");
        loanBook(registerBook("Refactoring"), memberId, "2026-03-10");

        mockMvc.perform(post("/loans/{loanId}/return", returnedLoanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-03-21\"}"))
                .andExpect(status().isOk());

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[0].title").value("Refactoring"))
                .andExpect(jsonPath("$[0].loanedAt").value("2026-03-10"))
                .andExpect(jsonPath("$[0].returnedAt").isEmpty())
                .andExpect(jsonPath("$[0].lateFee").isEmpty())
                .andExpect(jsonPath("$[0].loanId").isNotEmpty())
                .andExpect(jsonPath("$[1].loanId").value(returnedLoanId))
