package com.example.lending.application.service;

import com.example.lending.application.port.in.ListActiveLoansUseCase;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.domain.Book;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.Loan;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.function.Function;
import java.util.stream.Collectors;

@Service
@Transactional(readOnly = true)
public class ListActiveLoansService implements ListActiveLoansUseCase {

    private final LoadMemberPort loadMemberPort;
    private final LoadLoanPort loadLoanPort;
    private final LoadBookPort loadBookPort;

    public ListActiveLoansService(LoadMemberPort loadMemberPort, LoadLoanPort loadLoanPort, LoadBookPort loadBookPort) {
        this.loadMemberPort = loadMemberPort;
        this.loadLoanPort = loadLoanPort;
        this.loadBookPort = loadBookPort;
    }

    @Override
    public ActiveLoanPage listActiveLoans(ListActiveLoansQuery query) {
        UUID memberId = query.memberId();
        loadMemberPort.loadMember(memberId).orElseThrow(() -> new MemberNotFoundException(memberId));

        long totalCount = loadLoanPort.countActiveLoansByMemberId(memberId);
        List<Loan> loans = loadLoanPort.loadActiveLoansByMemberId(memberId, query.page(), query.size());
        Map<UUID, String> titles = titlesByBookId(loans);

        List<ActiveLoan> items = loans.stream()
                .map(loan -> new ActiveLoan(loan.getId(), loan.getBookId(), titles.get(loan.getBookId()),
                        loan.getLoanedAt(), loan.getDueAt()))
                .toList();
        return new ActiveLoanPage(items, query.page(), query.size(), totalCount);
    }

    private Map<UUID, String> titlesByBookId(List<Loan> loans) {
        List<UUID> bookIds = loans.stream().map(Loan::getBookId).distinct().toList();
        Map<UUID, Book> booksById = loadBookPort.loadBooks(bookIds).stream()
                .collect(Collectors.toMap(Book::getId, Function.identity()));
        return bookIds.stream().collect(Collectors.toMap(Function.identity(), bookId -> {
            Book book = booksById.get(bookId);
            if (book == null) {
                throw new BookNotFoundException(bookId);
            }
            return book.getTitle();
        }));
    }
}
package com.example.lending.domain;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Objects;
import java.util.UUID;

public class Loan {

    static final int LOAN_PERIOD_DAYS = 14;
    static final long LATE_FEE_PER_DAY = 100L;

    private final UUID id;
    private final UUID bookId;
    private final UUID memberId;
    private final LocalDate loanedAt;
    private final LocalDate dueAt;
    private LocalDate returnedAt;
    private final CreditCheck creditCheck;

    private Loan(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt, LocalDate returnedAt,
                 CreditCheck creditCheck) {
        this.id = Objects.requireNonNull(id, "id");
        this.bookId = Objects.requireNonNull(bookId, "bookId");
        this.memberId = Objects.requireNonNull(memberId, "memberId");
        this.loanedAt = Objects.requireNonNull(loanedAt, "loanedAt");
        this.dueAt = Objects.requireNonNull(dueAt, "dueAt");
        if (dueAt.isBefore(loanedAt)) {
            throw new IllegalArgumentException("dueAt must not be before loanedAt");
        }
        this.returnedAt = returnedAt;
        this.creditCheck = Objects.requireNonNull(creditCheck, "creditCheck");
    }

    public static Loan start(UUID bookId, UUID memberId, LocalDate loanedAt, CreditCheck creditCheck) {
        Objects.requireNonNull(memberId, "memberId");
        creditCheck.ensureApproved(memberId);
        return new Loan(UUID.randomUUID(), bookId, memberId, loanedAt, loanedAt.plusDays(LOAN_PERIOD_DAYS), null,
                creditCheck);
    }

    public static Loan reconstitute(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt,
                                    LocalDate returnedAt, CreditCheck creditCheck) {
        return new Loan(id, bookId, memberId, loanedAt, dueAt, returnedAt, creditCheck);
    }

    public void returnOn(LocalDate returnedAt) {
        if (this.returnedAt != null) {
            throw new LoanAlreadyReturnedException(id);
        }
        Objects.requireNonNull(returnedAt, "returnedAt");
        if (returnedAt.isBefore(loanedAt)) {
            throw new IllegalArgumentException("returnedAt must not be before loanedAt");
        }
        this.returnedAt = returnedAt;
    }

    public boolean isOverdue(LocalDate today) {
        return today.isAfter(dueAt);
    }

    public long overdueDays() {
        if (returnedAt == null) {
            throw new IllegalStateException("loan is not returned yet: " + id);
        }
        return Math.max(0, ChronoUnit.DAYS.between(dueAt, returnedAt));
    }

    public long lateFee() {
        return overdueDays() * LATE_FEE_PER_DAY;
    }

    public UUID getId() {
        return id;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public LocalDate getLoanedAt() {
        return loanedAt;
    }

    public LocalDate getDueAt() {
        return dueAt;
    }

    public LocalDate getReturnedAt() {
        return returnedAt;
    }

    public CreditCheck getCreditCheck() {
        return creditCheck;
    }
}
